SELECT count(*) FILTER (WHERE public_model_id = 'ollama-stop-test/first') AS "first!", count(*) FILTER (WHERE public_model_id = 'ollama-stop-test/second' AND lifecycle_state = 'active' AND version = 1) AS "original!", count(*) FILTER (WHERE public_model_id IN ('ollama-stop-test/first', 'ollama-stop-test/second') AND lifecycle_state = 'active') AS "active!" FROM models WHERE provider_id = '40000000-0000-0000-0000-000000000001'
